import * as fs from "fs";
import * as path from "path";
import type { Backend } from "../../core/agentBackend";
import { agentMarkdownIsRelayManaged } from "../../core/agentRelay";

// A relay-managed agent file (frontmatter `tycoon_relay`) is owned by the
// routing save: every text heal and resync below leaves it alone, so the
// generated relay section, the preserved original body and the haiku wrapper
// model survive panel opens. Reverting the relay brings the file back to the
// heals' normal scope.
export { agentMarkdownIsRelayManaged };

/** The agent definition embedded in a capability pack. */
export interface PackAgent {
  /** Agent id, used as the `.claude/agents/<id>.md` file name. */
  id: string;
  /** Display name, rendered as the markdown H1 heading. */
  name: string;
  /** Model id written to YAML frontmatter (`model:`). */
  model: string;
  /** One-line role description used for the `description:` frontmatter field, and (unless `body` overrides it) the `## Role` section. */
  role: string;
  /** Pipe-delimited task-routing keywords for the `## Keywords` section. */
  keywords: string;
  /**
   * Optional foreign-LLM backend declaration, rendered as a `backend:`
   * frontmatter sub-block and parseable back via
   * `src/core/agentBackend.ts`'s `parseAgentBackend`. Omitted for a
   * plain Claude-native agent (the default when `backend` is absent).
   */
  backend?: Backend;
  /**
   * Optional full markdown body (everything after the `# <name>` H1
   * heading) that REPLACES the standard generated `## Role` / `##
   * Keywords` / `## Working discipline` template. Used for agents (e.g.
   * the foreign-LLM reviewers) whose canonical body text is
   * hand-authored and richer than the generic template — copied in
   * verbatim rather than reconstructed section-by-section. When
   * present, `role` is still required (used for the `description:`
   * frontmatter field) but its text is not otherwise rendered.
   */
  body?: string;
  /**
   * Optional roster tier. Omitted (undefined) for regular worker agents.
   * `"lead"` marks a team-lead coordinator that owns a set of worker
   * agents — installers and the ready-test skill must not treat lead
   * agents the same as regular workers (see `LEAD_AGENTS`). `"reviewer"`
   * marks the optional Review-pass agent (see `REVIEWER_AGENTS`) — it IS a
   * normal spawnable leaf worker (unlike a lead, it owns no team), the tier
   * exists only so install/remove can safely identify TycoonAgents-owned
   * `reviewer.md` files the same way lead removal does for `tier: lead`.
   */
  tier?: "lead" | "reviewer";
}

/**
 * Build the markdown content for a pack's domain agent file
 * (`.claude/agents/<id>.md`). Pure: no fs/vscode access, so this is
 * unit-testable. Output round-trips through `parseAgentMarkdown`.
 * Returns a string ending in a trailing newline.
 *
 * Regular agents (no `tier`) render exactly as before — a `model:`
 * frontmatter line only. Lead agents additionally emit a `tier: lead`
 * frontmatter line so downstream tooling (installers, the ready-test
 * skill) can recognize and skip them.
 *
 * `packId`, when supplied, additionally emits a `tycoon_pack: <packId>`
 * frontmatter line — a provenance marker recording that this file was
 * generated by TycoonAgents' pack installer for that pack (e.g. `"uefn"`).
 * `_handleInstallPack` (panel.ts) uses this marker via
 * {@link agentMarkdownHasTycoonMarker} to tell "ours, safe to refresh"
 * apart from "a legacy/foreign file that happens to share this id" before
 * overwriting an existing agent file. Frontmatter key order is fixed:
 * `name`, `description`, then `model`, then `tier` (if any), then
 * `tycoon_pack` (if any) — deterministic, no incidental churn.
 *
 * `name` and `description` are REQUIRED by Claude Code to register a
 * subagent (https://docs.claude.com/ ... subagents) — without them a
 * generated `.claude/agents/<id>.md` file is never registered, so
 * `subagent_type` can never spawn it. `name` is always `agent.id` (the
 * kebab-case slug Claude Code requires — NOT `agent.name`, which is a
 * Title Case display string like "Verse Expert"). `description` is
 * `agent.role` (falling back to `agent.name` if `role` is ever empty),
 * JSON-stringified so colons/quotes/newlines in free-text role prose can
 * never break the YAML frontmatter block.
 */

/**
 * The `## Working discipline` body appended to every NON-orchestrator agent's
 * generated markdown. Reinforces that workers/reviewers are LEAVES: they do
 * the work themselves, never spawn nested Task sub-agents (which the Claude
 * Code harness does not make block on their children — a nested spawn returns
 * premature "I'll report when it's done" narration with no writes), and never
 * return that narration as a result. Shared with
 * {@link resyncAgentDisciplineSection} so fresh installs and on-load resyncs
 * stay byte-identical.
 */
export const WORKING_DISCIPLINE_BODY =
  "- You are a LEAF: do the assigned task YOURSELF — reads, searches, and edits — with your own tools. Do NOT spawn Task or sub-agents; there is no delegation below you.\n" +
  "- BLOCK until the work is actually finished. Never end with a \"running in the background\", \"I'll report when it's done\", or \"waiting for another agent\" message — that is not a valid result. Return only once the files are written and verified.\n" +
  "- If the work genuinely cannot finish in one tool call, split it into bounded sequential calls run to completion in this same turn (chunking knobs, per-call timeout) — never end the turn to \"wait\" and never spawn a helper to do it.\n" +
  "- Never delete a temp or evidence file until, in this same turn, you have verified on disk that its durable destination (a doc comment, a report file, a commit) already holds the data it captured.\n" +
  "- Report the concrete outcome in under 250 words: what changed (file:line), how you verified it, and any open issues. State your actual sample size or coverage limit when it differs from what was asked — an honest smaller result is acceptable; an overclaimed one is a failure.\n" +
  "- Open with the outcome — what changed and whether it verified — never with restated context or process narration.\n" +
  "- Keep it plain prose plus file:line: no headings, no bullet-theater, no flattery or self-assessment adjectives. Every word costs orchestrator context at the most expensive model's price.\n" +
  "- Deliver exactly what the brief asked, at the scope it asked. Do not widen into cleanup, refactoring, documentation, or adjacent features — name anything adjacent worth doing in one line under open issues instead of doing it.";

/**
 * Read-only variant of {@link WORKING_DISCIPLINE_BODY} for `tier: reviewer`
 * agents and the search/retrieval agent: same leaf, blocking, chunking,
 * evidence and report-style rules, but no edits and the report carries
 * findings or a verdict rather than "what changed".
 */
export const WORKING_DISCIPLINE_READ_ONLY_BODY =
  "- You are a LEAF and READ-ONLY: do the assigned task YOURSELF — reads and searches — with your own tools. Do NOT edit, write, or create project files. Do NOT spawn Task or sub-agents; there is no delegation below you.\n" +
  "- BLOCK until the work is actually finished. Never end with a \"running in the background\", \"I'll report when it's done\", or \"waiting for another agent\" message — that is not a valid result. Return only once your findings or verdict are complete and checked against the code.\n" +
  "- If the work genuinely cannot finish in one tool call, split it into bounded sequential calls run to completion in this same turn (chunking knobs, per-call timeout) — never end the turn to \"wait\" and never spawn a helper to do it.\n" +
  "- Never delete a temp or evidence file until, in this same turn, you have verified on disk that its durable destination (a doc comment, a report file, a commit) already holds the data it captured.\n" +
  "- Report your findings or verdict in under 250 words, with file:line for each claim, how you checked it, and any open issues. State your actual sample size or coverage limit when it differs from what was asked — an honest smaller result is acceptable; an overclaimed one is a failure.\n" +
  "- Open with the outcome — the verdict or the answer — never with restated context or process narration.\n" +
  "- Keep it plain prose plus file:line: no headings, no bullet-theater, no flattery or self-assessment adjectives. Every word costs orchestrator context at the most expensive model's price.\n" +
  "- Deliver exactly what the brief asked, at the scope it asked. Do not widen into cleanup, refactoring, documentation, or adjacent features — name anything adjacent worth doing in one line under open issues instead of doing it.";

/** True for agents that must never edit: the reviewer tier and search/retrieval. */
export function isReadOnlyAgent(agent: { id: string; tier?: string }): boolean {
  return agent.tier === "reviewer" || agent.id === "search-retrieval";
}

/** The discipline body matching an agent's read/write role. */
export function workingDisciplineBodyFor(agent: { id: string; tier?: string }): string {
  return isReadOnlyAgent(agent) ? WORKING_DISCIPLINE_READ_ONLY_BODY : WORKING_DISCIPLINE_BODY;
}

/**
 * Render a `backend:` frontmatter sub-block matching the indented-child
 * shape `src/core/agentBackend.ts`'s `readAgentFrontmatter`/
 * `parseAgentBackend` expect (2-space-indented `key: value` lines, arrays
 * as `[a, b]`). Field order is fixed: vendor, transport, mcpServer, tools,
 * model, costModelClass, endpointEnv, apiKeyEnv — optional fields omitted
 * when absent.
 */
function renderBackendBlock(backend: Backend): string {
  const lines = ["backend:"];
  lines.push(`  vendor: ${backend.vendor}`);
  lines.push(`  transport: ${backend.transport}`);
  if (backend.mcpServer) lines.push(`  mcpServer: ${backend.mcpServer}`);
  if (backend.tools && backend.tools.length > 0) lines.push(`  tools: [${backend.tools.join(", ")}]`);
  lines.push(`  model: ${backend.model}`);
  lines.push(`  costModelClass: ${backend.costModelClass}`);
  if (backend.endpointEnv) lines.push(`  endpointEnv: ${backend.endpointEnv}`);
  if (backend.apiKeyEnv) lines.push(`  apiKeyEnv: ${backend.apiKeyEnv}`);
  return lines.join("\n") + "\n";
}

/** Reviewer denylist: no sub-agents and no edits. */
const REVIEWER_DISALLOWED_TOOLS = "Agent, Edit, Write";

/** Legacy claude-worker denylist (file/shell/web tools). Superseded: on Claude Code the agent runs natively. */
const LEGACY_CLAUDE_WORKER_DISALLOWED = "Agent, Read, Write, Edit, MultiEdit, NotebookEdit, Glob, Grep, Bash, PowerShell, WebFetch, WebSearch";

/** Frontmatter `disallowedTools` value for an agent, or undefined for none.
 * Every non-orchestrator agent is denied the spawn tool. claude-worker keeps
 * its file/shell tools too: on the Claude Code harness it runs natively as a
 * normal Claude subagent (the claude-cli bridge is only for Codex/OpenCode). */
export function agentDisallowedTools(agentId: string): string | undefined {
  if (agentId === "orchestrator") return undefined;
  // The reviewer only reads and judges; it is also denied the edit tools.
  if (agentId === "reviewer") return REVIEWER_DISALLOWED_TOOLS;
  return "Agent";
}

export function buildAgentMarkdown(agent: {
  id: string;
  name: string;
  model: string;
  role: string;
  keywords: string;
  tier?: "lead" | "reviewer";
  backend?: Backend;
  body?: string;
}, packId?: string): string {
  const description = agent.role && agent.role.trim() !== "" ? agent.role : agent.name;
  return (
    "---\n" +
    `name: ${agent.id}\n` +
    `description: ${JSON.stringify(description)}\n` +
    `model: ${agent.model}\n` +
    // Config-level enforcement of the leaf-worker rule: the prose-only
    // "Working discipline" section below could be ignored, so every
    // non-orchestrator agent also gets a first-class denylist on the
    // sub-agent-spawning tool (named `Agent` since Claude Code v2.1.63).
    // CAVEAT: this frontmatter only binds a spawn that uses this agent's
    // custom NAME as `subagent_type` (Claude Code loads the .md and applies
    // its config only on that path) — a spawn using the BUILT-IN
    // `general-purpose` subagent_type never loads this file, so
    // `disallowedTools` never applies to it. The PreToolUse spawn guard in
    // hooks/tycoon-claude-hook.cjs is the enforcement that covers ALL
    // spawn paths, not just the named-agent one.
    (agentDisallowedTools(agent.id) ? `disallowedTools: ${agentDisallowedTools(agent.id)}\n` : "") +
    (agent.tier ? `tier: ${agent.tier}\n` : "") +
    (packId ? `tycoon_pack: ${packId}\n` : "") +
    (agent.backend ? renderBackendBlock(agent.backend) : "") +
    "---\n" +
    "\n" +
    `# ${agent.name}\n` +
    "\n" +
    (agent.body !== undefined
      ? agent.body
      : "## Role\n" +
        `${agent.role}\n` +
        "\n" +
        "## Keywords (for task routing)\n" +
        `${agent.keywords}\n` +
        // Leaf-worker discipline on every agent EXCEPT the orchestrator (the
        // only agent that is meant to delegate). Kept as the trailing
        // section so the on-load resync can find/append it deterministically.
        (agent.id !== "orchestrator"
          ? "\n## Working discipline\n" + workingDisciplineBodyFor(agent) + "\n"
          : ""))
  );
}

/**
 * Detect TycoonAgents' `tycoon_pack:` provenance marker in an existing
 * agent `.md` file's frontmatter text. Pure (no fs/vscode access), inverse
 * of the `tycoon_pack` line {@link buildAgentMarkdown} writes when given a
 * `packId`. Used by `_handleInstallPack` to distinguish "this file was
 * written by our installer (safe to refresh in place)" from "this file is
 * a legacy/foreign same-named agent (back it up before replacing)".
 */
export function agentMarkdownHasTycoonMarker(content: string): boolean {
  const lines = content.split(/\r\n|\n/);
  if (lines.length === 0 || lines[0] !== "---") {
    return false;
  }
  for (let i = 1; i < lines.length; i++) {
    if (lines[i] === "---") {
      break;
    }
    if (/^\s*tycoon_pack\s*:\s*\S+\s*$/.test(lines[i])) {
      return true;
    }
  }
  return false;
}

/** Provenance comment written by agent files from the product's old name,
 * e.g. `<!-- OfficeAgents Core Agent -->` or `<!-- OfficeAgents Verification Agent -->`. */
const LEGACY_OFFICEAGENTS_MARKER_RE = /<!--\s*OfficeAgents\s+(?:[\w-]+\s+)*Agent\s*-->/;

/** True when the file carries a legacy OfficeAgents provenance comment. */
export function agentMarkdownHasLegacyOfficeAgentsMarker(content: string): boolean {
  return LEGACY_OFFICEAGENTS_MARKER_RE.test(content);
}

/**
 * Heal a legacy OfficeAgents agent file that lacks the `name:` / `description:`
 * frontmatter Claude Code requires for subagents. Adds ONLY the missing
 * fields (`name` is the file's id, `description` the supplied text); no other
 * line or line ending changes, and the only `model:` change is a pinned Claude id (haiku/sonnet/opus/fable) becoming its alias; body text is untouched. Returns `null` when the
 * legacy marker is absent, nothing is missing, or the file's shape is not
 * recognised.
 */
export function healLegacyOfficeAgentsFrontmatter(content: string, agentId: string, description: string): string | null {
  if (agentMarkdownIsRelayManaged(content)) {
    return null;
  }
  if (!agentMarkdownHasLegacyOfficeAgentsMarker(content)) {
    return null;
  }
  const eol = content.includes("\r\n") ? "\r\n" : "\n";
  const fmMatch = /^---\r?\n([\s\S]*?)\r?\n---\r?\n/.exec(content);
  if (!fmMatch) {
    if (/^\s*(<!--[\s\S]*?-->\s*)*---\r?\n/.test(content)) {
      return null; // frontmatter preceded by other text: shape not recognised
    }
    const block = ["---", `name: ${agentId}`, `description: ${JSON.stringify(description)}`, "---"].join(eol) + eol;
    return block + content;
  }
  const lines = fmMatch[1].split(/\r\n|\n/);
  const add: string[] = [];
  if (!lines.some((l) => /^name\s*:/.test(l))) {
    add.push(`name: ${agentId}`);
  }
  if (!lines.some((l) => /^description\s*:/.test(l))) {
    add.push(`description: ${JSON.stringify(description)}`);
  }
  // Legacy files only: a pinned Claude id becomes its always-latest alias.
  let modelChanged = false;
  const fmText = fmMatch[1].replace(/^(model\s*:\s*)["']?claude-(haiku|sonnet|opus|fable)-[^\s"']*["']?([ \t]*)$/m, (_m, pre: string, fam: string, tail: string) => {
    modelChanged = true;
    return `${pre}${fam}${tail}`;
  });
  if (add.length === 0 && !modelChanged) {
    return null;
  }
  const open = fmMatch[0].startsWith("---\r\n") ? 5 : 4;
  const rest = content.slice(open + fmMatch[1].length);
  return "---" + eol + add.map((l) => l + eol).join("") + fmText + rest;
}

/**
 * Heal every legacy-marked `*.md` directly inside `agentsDir` (including ids
 * with no known template). `knownDescription(id)` supplies the template
 * description; otherwise a generic one is derived from the first heading.
 * Skips non-`.md` (so `.bak`), symlinks and anything resolving outside the
 * directory. Idempotent. Returns the ids written.
 */
export function healLegacyAgentFilesInDir(agentsDir: string, knownDescription?: (id: string) => string | undefined): string[] {
  const written: string[] = [];
  let names: string[];
  try {
    names = fs.readdirSync(agentsDir);
  } catch {
    return written;
  }
  for (const file of names) {
    if (!file.endsWith(".md")) continue;
    try {
      const filePath = path.join(agentsDir, file);
      if (path.dirname(path.resolve(filePath)) !== path.resolve(agentsDir)) continue;
      if (!fs.lstatSync(filePath).isFile()) continue;
      const content = fs.readFileSync(filePath, "utf8");
      if (!agentMarkdownHasLegacyOfficeAgentsMarker(content)) continue;
      const id = file.slice(0, -3);
      const heading = /^#\s+(.+?)\s*$/m.exec(content)?.[1];
      const description = knownDescription?.(id) ?? (heading ? `${heading} agent` : `${id} agent`);
      const healed = healLegacyOfficeAgentsFrontmatter(content, id, description);
      if (healed !== null) {
        fs.writeFileSync(filePath, healed);
        written.push(id);
      }
    } catch {
      /* best-effort per file */
    }
  }
  return written;
}

/**
 * Read the `tier:` frontmatter value from an agent markdown file's content,
 * if any. Pure (no fs/vscode access), inverse of the `tier` line
 * {@link buildAgentMarkdown} writes. This is the safety predicate used
 * before deleting a `.claude/agents/<id>.md` file when downgrading out of
 * Team Leads mode: only a file whose frontmatter says `tier: lead` is
 * eligible for removal, so a user's own file that happens to share an id
 * like `build-lead.md` (but wasn't written by TycoonAgents) is never
 * deleted.
 */
export function agentMarkdownTier(content: string): string | undefined {
  const lines = content.split(/\r\n|\n/);
  if (lines.length === 0 || lines[0] !== "---") {
    return undefined;
  }
  for (let i = 1; i < lines.length; i++) {
    if (lines[i] === "---") {
      break;
    }
    const match = /^\s*tier\s*:\s*(\S+)\s*$/.exec(lines[i]);
    if (match) {
      return match[1];
    }
  }
  return undefined;
}

/**
 * Secondary "is this file ours" signal for regular worker agents installed
 * before buildAgentMarkdown was passed a packId (so they predate the
 * tycoon_pack marker). Considers a file a positive match for `agent` only
 * if its frontmatter `model:` line equals `agent.model` AND its
 * `## Keywords (for task routing)` section body equals `agent.keywords`
 * exactly — keywords are a distinctive pipe-delimited fingerprint a user
 * is very unlikely to have hand-authored identically, so this is safe
 * without requiring the marker. Used only as a fallback alongside
 * agentMarkdownHasTycoonMarker, never as the sole signal for anything
 * destructive beyond a Role-section text swap.
 */
// Previous default `model:` aliases for agents whose catalog default changed,
// so unmarked files installed under the old default still fingerprint as ours.
const LEGACY_DEFAULT_MODELS: Record<string, string[]> = {
  "codex-reviewer": ["sonnet"],
  "gemini-reviewer": ["sonnet"],
  "kimi-reviewer": ["sonnet"],
  "grok-reviewer": ["sonnet"],
};

/**
 * Known-prior default keyword patterns TycoonAgents used to ship, keyed by
 * agent id, for ids whose current default has since changed. Used to migrate
 * agent-keywords.json entries and agent-file `## Keywords` bodies forward when
 * (and only when) they exactly equal a prior default, and by
 * {@link workerAgentFingerprintMatches} so un-migrated files still count as ours.
 */
export const SUPERSEDED_DEFAULT_KEYWORDS: Record<string, string[]> = {
  "quality-lead": ["quality|verify|test plan|acceptance|audit"],
  reviewer: ["review|verify|approve|correctness|quality|regression"],
  "uefn-auditor": ["verse|uefn|fortnite|verse-audit|verse-review|verse-lint"],
  "web-qa": ["playwright|browser|ui|qa|screenshot|accessibility|e2e|web"],
};

/**
 * Previously shipped `description:`/role texts per agent id. A frontmatter
 * description that exactly equals one of these is ours and untouched, so it
 * is moved to the current text; any other value is a user edit and is kept.
 */
export const SUPERSEDED_ROLES: Record<string, string[]> = {
  "ux-ui-designer": ["Designs and implements the visual layer — scene, layout, styling, and animation — so activity reads clearly at a glance."],
  "workspace-monitor": ["Turns provider hook events into normalized agent states for the visualization — the agent-activity and lifecycle-tracking specialist."],
};

/** Previously shipped H1 titles per agent id (exact match means untouched). */
export const SUPERSEDED_AGENT_NAMES: Record<string, string[]> = {
  "uefn-auditor": ["Verse Auditor"],
};

/**
 * Rewrite a superseded H1 title of a TycoonAgents-managed (tycoon_pack
 * marked) agent file to its current name. Only the exact old H1 line
 * changes. Returns null when nothing applies.
 */
export function healSupersededAgentTitle(content: string, agent: { id: string; name: string }): string | null {
  if (agentMarkdownIsRelayManaged(content)) {
    return null;
  }
  const prior = SUPERSEDED_AGENT_NAMES[agent.id];
  if (!prior || !agentMarkdownHasTycoonMarker(content)) return null;
  const fm = /^---\r?\n[\s\S]*?\r?\n---\r?\n/.exec(content);
  if (!fm) return null;
  const rest = content.slice(fm[0].length);
  const m = /^(\s*)# ([^\r\n]*?)[ \t]*(\r?\n|$)/.exec(rest);
  if (!m || !prior.includes(m[2]) || m[2] === agent.name) return null;
  const headEnd = fm[0].length + m[1].length;
  return content.slice(0, headEnd) + `# ${agent.name}` + content.slice(headEnd + 2 + m[2].length);
}

/**
 * If the `## Keywords (for task routing)` body line of `content` exactly
 * equals a superseded default for `agentId` (and differs from `current`),
 * return the content with just that line replaced by `current`, preserving
 * line endings. Otherwise null.
 */
export function refreshSupersededKeywordsBody(content: string, agentId: string, current: string): string | null {
  const prior = SUPERSEDED_DEFAULT_KEYWORDS[agentId];
  if (!prior || current === undefined || current.trim() === "") return null;
  const m = /## Keywords \(for task routing\)(\r?\n)([^\r\n]*)/.exec(content);
  if (!m) return null;
  const line = m[2];
  if (line.trim() === current || !prior.includes(line.trim())) return null;
  const start = m.index + m[0].length - line.length;
  return content.slice(0, start) + current + content.slice(start + line.length);
}

export function workerAgentFingerprintMatches(content: string, agent: PackAgent): boolean {
  const lines = content.split(/\r\n|\n/);
  if (lines.length === 0 || lines[0] !== "---") {
    return false;
  }
  let modelMatches = false;
  for (let i = 1; i < lines.length; i++) {
    if (lines[i] === "---") {
      break;
    }
    const match = /^\s*model\s*:\s*(\S+)\s*$/.exec(lines[i]);
    if (match) {
      // A pre-repair legacy file may carry a vendor-prefixed value (e.g.
      // `anthropic/haiku`) where the current catalog says `haiku` — match
      // either the exact alias or that vendor-prefixed form. A backend-
      // carrying agent's legacy file (codex-reviewer, gemini-reviewer,
      // kimi-reviewer, claude-worker) instead observed in the wild copied
      // its own `backend.model` id (e.g. `openai/gpt-6.1-sol`) into the
      // top-level `model:` line, so also accept an exact match against
      // `agent.backend.model` when present.
      modelMatches =
        match[1] === agent.model ||
        match[1].endsWith(`/${agent.model}`) ||
        (agent.backend !== undefined && match[1] === agent.backend.model) ||
        (LEGACY_DEFAULT_MODELS[agent.id] ?? []).includes(match[1]);
      break;
    }
  }
  if (!modelMatches) {
    return false;
  }

  const heading = "## Keywords (for task routing)\n";
  const headingIdx = content.indexOf(heading);
  if (headingIdx === -1) {
    return false;
  }
  const rest = content.slice(headingIdx + heading.length);
  const lineEnd = rest.indexOf("\n");
  const keywordsLine = lineEnd === -1 ? rest : rest.slice(0, lineEnd);
  const kw = keywordsLine.trim();
  return kw === agent.keywords || (SUPERSEDED_DEFAULT_KEYWORDS[agent.id] ?? []).includes(kw);
}

/**
 * Surgically replace the `## Role` section body in an agent markdown file
 * with `newRole`, preserving frontmatter and every other section
 * byte-for-byte. Returns the updated content, or the input content
 * unchanged if the current Role text already equals newRole, or `null` if
 * no `## Role\n...\n\n##` section shape is found (never touch a file whose
 * shape we don't recognize). Inverse-adjacent to buildAgentMarkdown's exact
 * output shape: `"## Role\n" + role + "\n\n" + "## Keywords ..."`.
 */
export function resyncAgentRoleSection(content: string, newRole: string, agentId?: string): string | null {
  if (agentMarkdownIsRelayManaged(content)) {
    return null;
  }
  const heading = "## Role\n";
  const headingIdx = content.indexOf(heading);
  if (headingIdx === -1) {
    return null;
  }
  const bodyStart = headingIdx + heading.length;
  const rest = content.slice(bodyStart);

  const blankLineIdx = rest.indexOf("\n\n");
  const nextHeadingMatch = /\n## /.exec(rest);
  const nextHeadingIdx = nextHeadingMatch ? nextHeadingMatch.index : -1;

  let bodyEnd = rest.length;
  if (blankLineIdx !== -1) {
    bodyEnd = blankLineIdx;
  }
  if (nextHeadingIdx !== -1 && nextHeadingIdx < bodyEnd) {
    bodyEnd = nextHeadingIdx;
  }

  const currentBody = rest.slice(0, bodyEnd);
  if (currentBody === newRole) {
    return content;
  }
  // Silent heal: only a paragraph that is exactly a previously shipped role text
  // for this agent is ours to replace; anything else is the user's wording.
  const shipped = agentId ? (SUPERSEDED_ROLES[agentId] ?? []) : [];
  if (!shipped.includes(currentBody)) {
    return content;
  }

  return content.slice(0, bodyStart) + newRole + rest.slice(bodyEnd);
}

/** Top-level `model:` values Claude Code accepts without substitution
 * (family aliases + `inherit`) or a full Anthropic model id (`claude-...`).
 * A vendor-prefixed id like `anthropic/haiku` or `openai/gpt-5` is not in
 * this set and gets rewritten to `agent.model` by
 * {@link resyncAgentFrontmatterFields}. */
const VALID_TOP_LEVEL_MODELS = new Set(["sonnet", "opus", "haiku", "inherit", "fable", "opusplan"]);

/** True for a top-level `model:` Claude Code accepts: a family alias with an
 * optional `[1m]` suffix, `inherit`/`opusplan`, or a `claude-*` id with or
 * without `[1m]`. Surrounding quotes are ignored. */
export function isClaudeTopLevelModel(value: string): boolean {
  const v = value.trim().replace(/^["']|["']$/g, "").replace(/\[1m\]$/i, "");
  return VALID_TOP_LEVEL_MODELS.has(v) || /^claude-/.test(v);
}

/** Vendor declared inside the top-level `backend:` block only (an indented
 * `vendor:` key elsewhere is ignored). */
function backendBlockVendor(lines: string[]): string | undefined {
  const start = lines.findIndex((l) => /^backend\s*:/.test(l));
  if (start === -1) return undefined;
  for (let i = start + 1; i < lines.length && /^\s+\S|^\s*$/.test(lines[i]); i++) {
    const m = /^\s+vendor\s*:\s*["']?([^\s"']+)/.exec(lines[i]);
    if (m) return m[1];
  }
  return undefined;
}

/**
 * Repair a managed agent file's frontmatter when it predates the `name`/
 * `description` fields Claude Code requires to register a custom subagent
 * (installed by an older `buildAgentMarkdown` that didn't emit them, or
 * hand-authored before that requirement was known), or when its top-level
 * `model:` is a vendor-prefixed id instead of an allowed family alias.
 * Only the frontmatter block is touched — `name`/`description` are inserted
 * when absent and an invalid top-level `model:` line is rewritten to
 * `agent.model`; a nested `backend.model` line (2+ space indent) is never
 * touched, since that is where vendor routing info belongs. Every line
 * below the closing `---` — the body, including any user edits — is
 * preserved byte-for-byte. Returns `null` when the frontmatter already has
 * both required fields and a valid model (no-op), or when no `---\n...\n---`
 * block is found at all (never touch a file whose shape isn't recognized).
 */
export function resyncAgentFrontmatterFields(content: string, agent: PackAgent): string | null {
  if (agentMarkdownIsRelayManaged(content)) {
    return null;
  }
  const fmMatch = /^---\r?\n([\s\S]*?)\r?\n---\r?\n/.exec(content);
  if (!fmMatch) {
    return null;
  }
  const eol = fmMatch[0].includes("\r\n") ? "\r\n" : "\n";
  const lines = fmMatch[1].split(/\r\n|\n/);

  const hasName = lines.some((l) => /^name\s*:/.test(l));
  const hasDescription = lines.some((l) => /^description\s*:/.test(l));
  const description = agent.role && agent.role.trim() !== "" ? agent.role : agent.name;

  let changed = false;
  const prefixLines: string[] = [];
  if (!hasName) {
    prefixLines.push(`name: ${agent.id}`);
    changed = true;
  }
  if (!hasDescription) {
    prefixLines.push(`description: ${JSON.stringify(description)}`);
    changed = true;
  }

  // A foreign-backend agent (backend.vendor set and not "anthropic") must
  // never carry its vendor's model slug (e.g. "openai/gpt-6-astra") as the
  // TOP-LEVEL `model:` — Claude Code sends that value straight to the
  // Anthropic API and 404s before the agent ever reaches its MCP backend
  // (see docs/codex-reviewer-onboarding-friction-2026-09-18.md). Rewriting
  // to a Claude alias (agent.model, "sonnet" by default in the catalog) is
  // mandatory whenever backend.vendor is foreign, not just when the value
  // fails the generic VALID_TOP_LEVEL_MODELS check, so a hand-edited file
  // that already has a *valid-looking* but wrong vendor slug still gets
  // corrected. When the rewritten value is lost, it is preserved under
  // `backend.model` if that field isn't already set explicitly.
  // A backend block already in the file (e.g. written by the routing
  // write-through) also marks the agent foreign, even for an agent whose
  // catalog entry has no backend.
  const fileVendor = backendBlockVendor(lines);
  const fileHasForeignBackend = fileVendor !== undefined && fileVendor !== "anthropic";
  const isForeignBackend = (agent.backend !== undefined && agent.backend.vendor !== "anthropic") || fileHasForeignBackend;
  const wrapperModel = isClaudeTopLevelModel(agent.model)
    ? agent.model
    : (/relay/.test(agent.body ?? "") ? "haiku" : "sonnet");
  let strandedVendorModel: string | undefined;

  const fixedLines = lines.map((l) => {
    const m = /^(\s*)model\s*:\s*(.+?)\s*$/.exec(l);
    if (!m || m[1].length > 0) {
      return l; // not a model line, or a nested (indented) one like backend.model
    }
    const isValidAlias = isClaudeTopLevelModel(m[2]);
    if (isValidAlias && !isForeignBackend) {
      return l;
    }
    if (isValidAlias && isForeignBackend) {
      // Already a Claude alias at top level — nothing to rewrite, but this
      // isn't itself a "changed" edit.
      return l;
    }
    changed = true;
    strandedVendorModel = m[2];
    return `model: ${wrapperModel}`;
  });

  if (isForeignBackend && strandedVendorModel !== undefined) {
    const hasExplicitBackendModel = lines.some((l) => /^\s+model\s*:\s*\S/.test(l));
    if (!hasExplicitBackendModel) {
      const backendLineIdx = fixedLines.findIndex((l) => /^backend\s*:\s*$/.test(l) || /^backend\s*:/.test(l));
      if (backendLineIdx === -1) {
        fixedLines.push("backend:", `  model: ${strandedVendorModel}`);
      } else {
        fixedLines.splice(backendLineIdx + 1, 0, `  model: ${strandedVendorModel}`);
      }
      changed = true;
    }
  }

  // claude-worker only: upgrade a missing or legacy file/shell-denying
  // `disallowedTools`. Any other value (user customization, YAML block list)
  // is left alone; other agents' values are never touched.
  const desiredDisallowed = agentDisallowedTools(agent.id);
  if (agent.id === "claude-worker" && desiredDisallowed !== undefined && lines.some((l) => /^tycoon_pack\s*:/.test(l))) {
    const idx = fixedLines.findIndex((l) => /^disallowedTools\s*:/.test(l));
    const wanted = `disallowedTools: ${desiredDisallowed}`;
    if (idx === -1) {
      fixedLines.push(wanted);
      changed = true;
    } else if (fixedLines[idx].replace(/^disallowedTools\s*:\s*/, "").trim().replace(/^["']|["']$/g, "") === LEGACY_CLAUDE_WORKER_DISALLOWED && /^## Which route/m.test(content)) {
      fixedLines[idx] = wanted;
      changed = true;
    }
  }

  // Description still equal to a previously shipped text: move to the current one.
  if (hasDescription) {
    const dIdx = fixedLines.findIndex((l) => /^description\s*:/.test(l));
    const priorRoles = SUPERSEDED_ROLES[agent.id] ?? [];
    if (dIdx !== -1 && priorRoles.length > 0) {
      const raw = fixedLines[dIdx].replace(/^description\s*:\s*/, "").trim();
      if (priorRoles.some((r) => raw === JSON.stringify(r)) && raw !== JSON.stringify(description)) {
        fixedLines[dIdx] = `description: ${JSON.stringify(description)}`;
        changed = true;
      }
    }
  }

  // reviewer: an untouched "Agent" denylist gains Edit and Write.
  if (agent.id === "reviewer" && (lines.some((l) => /^tycoon_pack\s*:/.test(l)) || lines.some((l) => /^tier\s*:\s*reviewer\s*$/.test(l)))) {
    const idx = fixedLines.findIndex((l) => /^disallowedTools\s*:/.test(l));
    if (idx !== -1 && fixedLines[idx].replace(/^disallowedTools\s*:\s*/, "").trim().replace(/^["']|["']$/g, "") === "Agent") {
      fixedLines[idx] = `disallowedTools: ${REVIEWER_DISALLOWED_TOOLS}`;
      changed = true;
    }
  }

  const rebuilt = changed
    ? "---" + eol + [...prefixLines, ...fixedLines].join(eol) + eol + "---" + eol + content.slice(fmMatch[0].length)
    : content;
  const retitled = healSupersededAgentTitle(rebuilt, agent);
  if (retitled !== null) return retitled;
  return changed ? rebuilt : null;
}

/**
 * Heal a clobbered top-level `model:` on any agent file that carries a
 * `backend:` block with a non-anthropic vendor. The top-level value is the
 * Claude Code subagent's own model and must be a Claude alias or claude-* id;
 * a vendor id there (e.g. `google/gemini-2.5-pro`) makes Claude Code 404 on
 * launch. Restores `catalogModel` when it is a valid alias, else `haiku` for
 * relay wrappers and `sonnet` otherwise. Returns null when nothing to heal.
 */
/**
 * Update an installed claude-worker whose body is EXACTLY the previously shipped
 * one (always call the `claude` tool) to the current body, which runs natively on
 * Claude Code. A user-edited body is never touched. Returns null when nothing to do.
 */
export function healClaudeWorkerBody(content: string): string | null {
  if (agentMarkdownIsRelayManaged(content)) {
    return null;
  }
  const fm = /^---\r?\n[\s\S]*?\r?\n---\r?\n/.exec(content);
  if (!fm || !/^tycoon_pack\s*:/m.test(fm[0])) return null;
  const agent = FOREIGN_LLM_AGENTS.find((a) => a.id === "claude-worker");
  if (!agent || agent.body === undefined) return null;
  const eol = fm[0].includes("\r\n") ? "\r\n" : "\n";
  const legacyBody = agent.body
    .replace(/^## Which route\n[\s\S]*?(?=^## )/m, "")
    .replace("On the bridge route, use the `claude` tool. Always pass:", "Use the `claude` tool. Always pass:");
  const rest = content.slice(fm[0].length).replace(/\r\n/g, "\n");
  const header = `\n# ${agent.name}\n\n`;
  if (rest !== header + legacyBody) return null;
  return fm[0] + (header + agent.body).replace(/\n/g, eol);
}

export function healForeignWrapperModel(
  content: string,
  catalogModel?: string,
): { content: string; from: string; to: string } | null {
  if (agentMarkdownIsRelayManaged(content)) return null;
  const fmMatch = /^---\r?\n([\s\S]*?)\r?\n---\r?\n/.exec(content);
  if (!fmMatch) return null;
  const lines = fmMatch[1].split(/\r\n|\n/);
  const vendor = backendBlockVendor(lines);
  if (vendor === undefined || vendor === "anthropic") return null;
  const idx = lines.findIndex((l) => /^model\s*:\s*\S/.test(l));
  if (idx === -1) return null;
  const current = /^model\s*:\s*(.+?)\s*$/.exec(lines[idx])![1].replace(/^["']|["']$/g, "");
  if (isClaudeTopLevelModel(current)) return null;
  const to = catalogModel !== undefined && isClaudeTopLevelModel(catalogModel)
    ? catalogModel
    : (/wrapper-class:\s*relay/.test(content) ? "haiku" : "sonnet");
  lines[idx] = `model: ${to}`;
  const eol = fmMatch[0].includes("\r\n") ? "\r\n" : "\n";
  return { content: "---" + eol + lines.join(eol) + eol + "---" + eol + content.slice(fmMatch[0].length), from: current, to };
}

/**
 * Every `## Working discipline` body TycoonAgents has shipped (current worker,
 * current read-only, and the two earlier worker versions). The heal replaces a
 * section only when its body equals one of these exactly; anything else is the
 * user's edit and stays untouched.
 */
// MAINTAINERS: any change to WORKING_DISCIPLINE_BODY or WORKING_DISCIPLINE_READ_ONLY_BODY
// MUST add the OLD body to the list returned here. Installed files carrying an old
// body are only upgraded when they match a known shipped body exactly.
function knownDisciplineBodies(): string[] {
  const lines = WORKING_DISCIPLINE_BODY.split("\n");
  const v1 = [lines[0], lines[1], "- Report the concrete outcome in under 250 words: what changed (file:line), how you verified it, and any open issues."].join("\n");
  const v2 = lines.slice(0, 5).join("\n");
  return [WORKING_DISCIPLINE_BODY, WORKING_DISCIPLINE_READ_ONLY_BODY, v1, v2];
}

/**
 * Ensure a managed worker agent file carries the current `## Working
 * discipline` section (see {@link WORKING_DISCIPLINE_BODY}). The section it
 * owns runs from its heading to the next heading of level 1 or 2 (or EOF);
 * sections the user added before or after it are never part of that span.
 *  - present and current: returns the input content unchanged (idempotent);
 *  - present and EXACTLY a previously shipped body: only that body is replaced
 *    with the canonical one (surrounding blank lines and every other section
 *    are preserved byte-for-byte);
 *  - present but edited by the user: left alone;
 *  - ABSENT (file installed before the section existed): appended at the end.
 * Only ever call this for NON-orchestrator agents (the orchestrator delegates
 * and must not carry leaf-worker discipline).
 */
export function resyncAgentDisciplineSection(content: string): string {
  if (agentMarkdownIsRelayManaged(content)) {
    return content;
  }
  const eol = content.includes("\r\n") ? "\r\n" : "\n";
  // Read-only roles (reviewer tier, search-retrieval) are identified from the
  // file's own frontmatter so existing callers need no agent argument.
  const fm = /^---\r?\n([\s\S]*?)\r?\n---/.exec(content)?.[1] ?? "";
  const idMatch = /^name\s*:\s*["']?([^\s"']+)/m.exec(fm);
  const tierMatch = /^tier\s*:\s*(\S+)/m.exec(fm);
  const canonicalBody = workingDisciplineBodyFor({ id: idMatch?.[1] ?? "", tier: tierMatch?.[1] });
  const heading = /^## Working discipline[ \t]*(?:\r?\n|$)/m.exec(content);
  if (!heading) {
    const base = content.endsWith("\n") ? content : content + eol;
    return base + eol + "## Working discipline" + eol + canonicalBody.replace(/\n/g, eol) + eol;
  }
  const bodyStart = heading.index + heading[0].length;
  const next = /^#{1,2} \S/m.exec(content.slice(bodyStart));
  const end = next ? bodyStart + next.index : content.length;
  const span = content.slice(bodyStart, end);
  const trailing = /\s*$/.exec(span)![0];
  const body = span.slice(0, span.length - trailing.length).replace(/\r\n/g, "\n");
  if (body === canonicalBody || !knownDisciplineBodies().includes(body)) {
    return content;
  }
  return content.slice(0, bodyStart) + canonicalBody.replace(/\n/g, eol) + trailing + content.slice(end);
}

interface MdSection { heading: string; text: string }

/** Split agent markdown into the part before the first `## ` heading and its `## ` sections (a `## ` line inside a code fence is not a heading). */
function splitAgentSections(text: string): { head: string; sections: MdSection[] } {
  const starts: Array<{ idx: number; heading: string }> = [];
  let fence: string | null = null;
  const re = /([^\r\n]*)(\r?\n|$)/g;
  let m: RegExpExecArray | null;
  while ((m = re.exec(text)) !== null) {
    if (m[0] === "" ) break;
    const line = m[1];
    const f = /^\s*(```|~~~)/.exec(line);
    if (f) {
      if (fence === null) fence = f[1];
      else if (f[1] === fence) fence = null;
    } else if (fence === null && /^## /.test(line)) {
      starts.push({ idx: m.index, heading: line.trim() });
    }
  }
  const head = text.slice(0, starts.length ? starts[0].idx : text.length);
  const sections = starts.map((st, i) => ({ heading: st.heading, text: text.slice(st.idx, i + 1 < starts.length ? starts[i + 1].idx : text.length) }));
  return { head, sections };
}

function sectionBody(sec: MdSection): string {
  return sec.text.replace(/\r\n/g, "\n").split("\n").slice(1).join("\n").trim();
}

/** True when this section body is exactly a version of that template section TycoonAgents shipped. */
function isShippedSectionBody(agentId: string, heading: string, body: string): boolean {
  if (heading === "## Role") return (SUPERSEDED_ROLES[agentId] ?? []).includes(body);
  if (heading === "## Keywords (for task routing)") return (SUPERSEDED_DEFAULT_KEYWORDS[agentId] ?? []).includes(body);
  if (heading === "## Working discipline") return knownDisciplineBodies().includes(body);
  return false;
}

/**
 * Regenerate a managed agent file from `generated` (the shipped template) while
 * keeping the user's additions.
 *  - Sections whose heading the template lacks (e.g. a user's `## Report Format`)
 *    stay where they were.
 *  - A user-renamed template heading (an unmatched section at the template
 *    section's own position) counts as the user's version and is kept, not duplicated.
 *  - Template sections missing from the file are appended.
 *  - Explicit mode (default, a user click): matching template sections and the
 *    frontmatter/title are regenerated.
 *  - `silent: true` (no click): the frontmatter/title stay as they are and a
 *    template section is regenerated only when the file's copy exactly equals a
 *    known shipped version; otherwise the user's section is kept.
 * Idempotent: merging its own output returns it unchanged.
 */
export function regenerateAgentMarkdownKeepingExtras(existing: string, generated: string, opts: { silent?: boolean } = {}): string {
  const silent = opts.silent === true;
  const eol = existing.includes("\r\n") ? "\r\n" : "\n";
  const toEol = (t: string): string => t.replace(/\r?\n/g, eol);
  const g = splitAgentSections(generated);
  const e = splitAgentSections(existing);
  const agentId = /^name\s*:\s*["']?([^\s"']+)/m.exec(/^---\r?\n([\s\S]*?)\r?\n---/.exec(generated)?.[1] ?? "")?.[1] ?? "";
  const gByHeading = new Map(g.sections.map((x) => [x.heading, x]));
  const eHeadings = new Set(e.sections.map((x) => x.heading));
  const consumed = new Set<string>(); // template headings already represented in the output
  const renamed = new Set<number>(); // existing indexes holding a user-renamed template section
  g.sections.forEach((gs, gi) => {
    if (eHeadings.has(gs.heading)) return;
    const cand = e.sections[gi];
    if (cand && !gByHeading.has(cand.heading)) {
      renamed.add(gi);
      consumed.add(gs.heading);
    }
  });
  const trailingWs = (t: string): string => /\s*$/.exec(t)![0];
  let out = silent ? e.head : toEol(g.head);
  e.sections.forEach((es, ei) => {
    const gs = gByHeading.get(es.heading);
    if (gs && !consumed.has(es.heading)) {
      consumed.add(es.heading);
      const keepUser = silent && !(sectionBody(es) === sectionBody(gs) || isShippedSectionBody(agentId, es.heading, sectionBody(es)));
      if (keepUser || sectionBody(es) === sectionBody(gs)) {
        out += es.text;
      } else {
        out += toEol(gs.text.replace(/\s+$/, "")) + trailingWs(es.text);
      }
      return;
    }
    out += es.text; // extra section or user-renamed template heading: untouched, in place
    void ei;
  });
  for (const gs of g.sections) {
    if (consumed.has(gs.heading) || eHeadings.has(gs.heading)) continue;
    if (out.length > 0 && !out.endsWith("\n")) out += eol;
    if (out.length > 0 && !/\n\s*\n$/.test(out)) out += eol;
    out += toEol(gs.text.replace(/\s+$/, "")) + eol;
  }
  return out;
}

